import { expect, waitFor, within } from "storybook/test";

import { PieChart } from "./index";

import type { Meta, StoryObj } from "@storybook/react-vite";

const meta = {
  title: "Data Viz/Pie Chart",
  component: PieChart,
  parameters: {
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof PieChart>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  name: "Default",
  parameters: {
    // Auto-generated by sync-storybook-zephyr - do not add manually
    zephyr: { testCaseId: "SW-T1012" },
  },
  args: {
    dataSeries: {
      labels: ["pH", "Temperature", "Dissolved Oxygen", "Cell Density", "Viability"],
      values: [12, 23, 35, 18, 12],
      name: "Bioreactor Parameters",
    },
    title: "Bioreactor",
    width: 480,
    height: 480,
    textInfo: "percent",
    hole: 0,
    rotation: 0,
  },
  play: async ({ canvasElement, step }) => {
    const canvas = within(canvasElement);

    await step("Chart title is displayed", async () => {
      expect(canvas.getByText("Bioreactor")).toBeInTheDocument();
    });

    await step("Chart container renders", async () => {
      await waitFor(
        () => {
          expect(canvasElement.querySelector("svg[data-viz-panel]")).toBeInTheDocument();
        },
        { timeout: 15000 },
      );
    });

    await step("Slices render", async () => {
      expect(canvasElement.querySelector('[data-polar="slices"]')).toBeInTheDocument();
      const slices = canvasElement.querySelectorAll('[data-polar="slices"] path');
      expect(slices.length).toBe(5);
    });

    await step("Each slice has its own fill", async () => {
      const fills = [...canvasElement.querySelectorAll('[data-polar="slices"] path')].map((node) =>
        node.getAttribute("fill"),
      );
      expect(new Set(fills).size).toBe(fills.length);
    });

    await step("Slices have a rendered size", async () => {
      const slices = [...canvasElement.querySelectorAll<SVGPathElement>('[data-polar="slices"] path')];
      slices.forEach((slice) => {
        const rect = slice.getBoundingClientRect();
        expect(rect.width).toBeGreaterThan(0);
        expect(rect.height).toBeGreaterThan(0);
      });
    });
  },
};

